/**
 * Turns the raw data checked into `tempAssets/` into the two static assets the
 * app ships:
 *
 *   src/assets/data/marker-catalog.json     positioned, categorised markers
 *   src/assets/data/map-tiles-index.json    which {z}/{y}/{x} tiles actually exist
 *
 * Marker positions are derived from Elden Ring's own MSB world coordinates
 * (via `tempAssets/compass-data/*.ts`, generated by EthanShoeDev/elden-ring-compass)
 * and projected to master-pixel space with the affine ported below from that
 * project's `apps/web/src/lib/map-affine.ts`. The tile pyramid those pixels index
 * into is the same one copied to `src/assets/map-tiles/`.
 *
 * Categories:
 *   bosses, sites-of-grace  — bosses.ts / graces.ts (curated name lists)
 *   dungeons, merchants     — derived from graces.ts / markers.ts
 *   golden-seeds, sacred-tears, larval-tears, memory-stones, talisman-pouches,
 *   crystal-tears, whetblades, bell-bearings, cookbooks, gloveworts
 *                           — placements.ts, filtered by item (goods.ts)
 *
 * Full write-up of the coordinate derivation: docs/map-coordinates.md
 *
 * Inputs (`tempAssets/compass-data/*.ts`) are committed; the raw tile source
 * (`tempAssets/maps/`) is not — see scripts/README.md and docs/adr/0002.
 *
 * When to run: after re-pulling compass-data or the tile pyramid. Runs
 * automatically before `npm start` (package.json `prestart`). Not part of
 * `npm run build` — production builds ship the committed JSON as-is.
 *
 * Run manually: `npm run prepare:map`
 */
import { readFileSync, readdirSync, existsSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { writeIfChanged } from './lib/write-if-changed.mjs';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const COMPASS = join(root, 'tempAssets', 'compass-data');
const TILES = join(root, 'src', 'assets', 'map-tiles');
const DATA_OUT = join(root, 'src', 'assets', 'data');
const MARKER_ICONS = join(root, 'src', 'assets', 'markers');
// Optional imagery from `npm run fetch:images` (Fan API). Absent on a bare clone
// until that script has run; the catalog just omits the images then.
const BOSS_IMAGES = (() => {
  const file = join(root, 'tempAssets', 'fan-api', 'boss-images.json');
  return existsSync(file) ? JSON.parse(readFileSync(file, 'utf8')) : {};
})();

const NATIVE_ZOOM = 6;
const MASTER_SIZE = 10496;

/** Read `export const NAME: ... = [ ... ];` from a generated .ts file as JSON. */
function parseExportedArray(file) {
  const text = readFileSync(join(COMPASS, file), 'utf8');
  const start = text.indexOf('= [');
  const end = text.lastIndexOf('];');
  if (start < 0 || end < 0) throw new Error(`Cannot parse array from ${file}`);
  const body = text.slice(start + 2, end + 1).replace(/,(\s*[\]}])/g, '$1');
  return JSON.parse(body);
}

/** Read `export const NAME: ... = JSON.parse("[ ... ]");` from a generated file. */
function parseJsonParseArray(file) {
  const text = readFileSync(join(COMPASS, file), 'utf8');
  const m = text.match(/JSON\.parse\((".*")\)/s);
  if (!m) throw new Error(`Cannot parse JSON.parse() payload from ${file}`);
  return JSON.parse(JSON.parse(m[1]));
}

// --- affine: MSB world coords -> master pixel --------------------------------
// Ported from elden-ring-compass/apps/web/src/lib/map-affine.ts. `px = worldX +
// OFFSET_X`, `py = OFFSET_Y - worldZ`, scale exactly 1px = 1 world-unit.
const OFFSET_X = -7168;
const OFFSET_Y = 16640;
const worldToMasterPixel = (master, worldX, worldZ) => ({
  master,
  px: worldX + OFFSET_X,
  py: OFFSET_Y - worldZ,
});

const legacyConv = parseExportedArray('world-map-legacy-conv.ts');
const legacyConvByBlock = new Map();
for (const c of legacyConv) {
  const list = legacyConvByBlock.get(c.srcMapId) ?? [];
  list.push(c);
  legacyConvByBlock.set(c.srcMapId, list);
}

/** The closest legacy-conversion point to `(x, z)`, or null if `points` is empty. */
function nearestConvPoint(points, x, z) {
  let best = null;
  let bestDist = Infinity;
  for (const p of points) {
    const d = (x - p.srcX) ** 2 + (z - p.srcZ) ** 2;
    if (d < bestDist) {
      bestDist = d;
      best = p;
    }
  }
  return best;
}

function dungeonMarkerToMasterPixel(mapId, x, z) {
  const block = /^(m\d\d_\d\d_\d\d)_/.exec(mapId)?.[1];
  const points = block && legacyConvByBlock.get(block);
  if (!points || points.length === 0) return null;
  const best = nearestConvPoint(points, x, z);
  return best ? worldToMasterPixel(best.master, x + best.addX, z + best.addZ) : null;
}

function markerToMasterPixel(mapId, x, z) {
  const m = /^m(60|61)_(\d+)_(\d+)_\d(\d)$/.exec(mapId);
  if (m) {
    const tier = Number(m[4]);
    if (tier > 2) return null;
    const size = 256 * 2 ** tier;
    return worldToMasterPixel(
      m[1] === '60' ? 'M00' : 'M10',
      Number(m[2]) * size + size / 2 + x,
      Number(m[3]) * size + size / 2 + z,
    );
  }
  return dungeonMarkerToMasterPixel(mapId, x, z);
}

const MASTER_TO_LAYER = { M00: 'overworld', M01: 'underground' };

// --- inputs ----------------------------------------------------------------
const BOSSES = parseExportedArray('bosses.ts');
const GRACES = parseExportedArray('graces.ts');
const MAP_MARKERS = parseExportedArray('markers.ts');
const GOODS = parseExportedArray('goods.ts');
const PLACEMENTS = parseJsonParseArray('placements.ts');

const goodsById = new Map(GOODS.map((g) => [g.id, g]));

/** Master pixel of every placed entity, and its raw MSB map id. */
const entityPixel = new Map();
const entityMapId = new Map();
for (const mk of MAP_MARKERS) {
  entityMapId.set(mk.entityId, mk.mapId);
  const p = markerToMasterPixel(mk.mapId, mk.x, mk.z);
  if (p) entityPixel.set(mk.entityId, p);
}

const markers = [];
const seen = new Set();
const push = (id, categoryId, name, p, completion, image, itemId) => {
  const layer = MASTER_TO_LAYER[p.master];
  if (!layer || seen.has(id)) return;
  seen.add(id);
  const marker = {
    id,
    categoryId,
    layer,
    x: Math.round(p.px),
    y: Math.round(p.py),
    name,
  };
  if (completion) marker.completion = completion;
  if (image) marker.image = image;
  if (itemId) marker.itemId = itemId;
  markers.push(marker);
};

// Marker Category -> Item Catalog id. Completing a marker in one of these
// categories also adds one of the Item to Inventory (and un-completing removes
// one) — see CONTEXT.md -> "Golden Seed" / "Sacred Tear". Only these two exist
// today; the mechanism is general so more can opt in later.
const CATEGORY_ITEM_LINK = {
  'golden-seeds': 'golden-seed',
  'sacred-tears': 'sacred-tear',
};

// --- boss tiers -----------------------------------------------------------
// The demigod / shardbearer / remembrance sets are lifted verbatim from
// elden-ring-compass' `apps/web/src/lib/boss-meta.ts` (wiki-verified there).
// Everything else falls back to a coarse arena-based guess, same as that file —
// good enough to pick the right defeat banner for the bosses that matter, not a
// hand-curated per-boss table.
const DEMIGOD_FLAGS = new Set([
  10000800, 11000800, 11050800, 12050800, 16000800, 15000800, 1252380800,
  21010800, 20010800,
]);
const SHARDBEARER_FLAGS = new Set([
  10000800, 1252380800, 16000800, 11000800, 12050800, 15000800, 14000800,
]);
const REMEMBRANCE_FLAGS = new Set([
  10000800, 11000800, 11050800, 12030850, 12040800, 12050800, 12090800,
  13000800, 13000830, 14000800, 15000800, 16000800, 19000800, 1052520800,
  1252380800, 19000810, 20000800, 20010800, 20020800, 21010800, 22000800,
  25000800, 28000800, 2044450800, 2048440800, 2049480800, 2054390800,
]);
const GOD_FLAGS = new Set([19000800, 19000810]);
const MINOR_DUNGEON_AREAS = new Set([30, 31, 32, 34, 39, 40, 41, 43]);

// Checked in this order: a flag in more than one set takes the earliest tier.
const TIER_BY_FLAG = [
  [GOD_FLAGS, 'god'],
  [DEMIGOD_FLAGS, 'demigod'],
  [SHARDBEARER_FLAGS, 'demigod'],
  [REMEMBRANCE_FLAGS, 'great-enemy'],
];

function isMinorDungeonArea(mapId) {
  const area = Number(/^m(\d+)_/.exec(mapId)?.[1] ?? -1);
  return area === 60 || area === 61 || MINOR_DUNGEON_AREAS.has(area);
}

/** 'god' | 'demigod' | 'great-enemy' | 'enemy' */
function bossTier(flag, mapId) {
  for (const [flags, tier] of TIER_BY_FLAG) {
    if (flags.has(flag)) return tier;
  }
  // legacy / main area (Stormveil, Leyndell, …) falls back to 'great-enemy'
  return isMinorDungeonArea(mapId) ? 'enemy' : 'great-enemy';
}

// All bosses share one category; only the defeat banner differs by tier.
const TIER_DONE_STATUS = {
  god: 'God Slain',
  demigod: 'Demigod Felled',
  'great-enemy': 'Great Enemy Felled',
  enemy: 'Enemy Felled',
};
const CATEGORY_DEFAULT_DONE = 'Enemy Felled';

for (const b of BOSSES) {
  if (!b.name) continue;
  const p = markerToMasterPixel(b.mapId, b.x, b.z);
  if (!p) continue;
  const doneStatus = TIER_DONE_STATUS[bossTier(b.defeatFlagId, b.mapId)];
  const completion =
    doneStatus === CATEGORY_DEFAULT_DONE
      ? undefined
      : { action: 'Mark boss as felled', doneStatus };
  push(`boss-${b.defeatFlagId}`, 'bosses', b.name, p, completion, BOSS_IMAGES[b.name]);
}

for (const g of GRACES) {
  const p = entityPixel.get(g.bonfireEntityId);
  if (p) push(`grace-${g.flagId}`, 'sites-of-grace', g.name, p);
}

// --- dungeons -----------------------------------------------------------
// No dedicated dungeon-entrance coordinates exist in the source data. Every
// minor dungeon (catacomb / cave / tunnel / hero's grave / shunning-grounds)
// has an interior Site of Grace that carries the dungeon's name, so we place
// one dungeon marker at that grace. Dungeons split across two graces (e.g.
// "Dragon's Pit" + "Dragon's Pit Terminus") are deduped by MSB map block to the
// lower bonfire entity id — the main entrance grace. Divine Towers (area 34) and
// the DLC (areas 41–43) are excluded; legacy dungeons (Stormveil, Raya Lucaria …)
// are whole areas, not point markers, and get none.
const DUNGEON_GRACE_AREAS = new Set([30, 31, 32, 35, 39, 40]);
const dungeonByBlock = new Map();
for (const g of GRACES) {
  if (!DUNGEON_GRACE_AREAS.has(g.mapArea)) continue;
  const block = /^(m\d\d_\d\d_\d\d)/.exec(
    entityMapId.get(g.bonfireEntityId) ?? '',
  )?.[1];
  if (!block) continue;
  const current = dungeonByBlock.get(block);
  if (!current || g.bonfireEntityId < current.bonfireEntityId) {
    dungeonByBlock.set(block, g);
  }
}
for (const g of dungeonByBlock.values()) {
  const p = entityPixel.get(g.bonfireEntityId);
  if (p) push(`dungeon-${g.flagId}`, 'dungeons', g.name, p);
}

// --- merchants --------------------------------------------------------
// The wandering merchants players hunt for Bell Bearings. Named quest-NPC
// vendors are out of scope. Positions come straight from markers.ts.
for (const mk of MAP_MARKERS) {
  if (mk.category !== 'npc' || !/Merchant/.test(mk.displayName ?? '')) continue;
  const p = entityPixel.get(mk.entityId);
  if (p) push(`merchant-${mk.entityId}`, 'merchants', mk.displayName, p);
}

// --- collectibles from placements ------------------------------------
// Each PLACEMENTS entry is one guaranteed pickup of a tracked item. RNG enemy
// drops (chance < 1) are excluded; placements landing on the same master pixel
// are collapsed. DLC placements (master M10) are dropped by `push()` — no tiles.
/** categoryId -> (good) => boolean */
const COLLECTIBLES = {
  'golden-seeds': (g) => g.id === 10010,
  'sacred-tears': (g) => g.id === 10020,
  'larval-tears': (g) => g.name === 'Larval Tear',
  'memory-stones': (g) => g.name === 'Memory Stone',
  'talisman-pouches': (g) => g.name === 'Talisman Pouch',
  'crystal-tears': (g) => g.category === 'Crystal Tear',
  whetblades: (g) => /Whetblade/.test(g.name),
  'bell-bearings': (g) => /Bell Bearing/.test(g.name),
  cookbooks: (g) => /Cookbook/.test(g.name),
  gloveworts: (g) => /Glovewort/.test(g.name),
};
const collectibleCategoryOf = (itemId) => {
  const g = goodsById.get(itemId);
  if (!g) return null;
  for (const [categoryId, match] of Object.entries(COLLECTIBLES)) {
    if (match(g)) return categoryId;
  }
  return null;
};

const collectibleSeen = new Set(); // `${categoryId}@${x},${y}`
for (const pl of PLACEMENTS) {
  if (pl.chance !== 1 || pl.itemType !== 'goods') continue;
  const categoryId = collectibleCategoryOf(pl.itemId);
  if (!categoryId) continue;
  const p = markerToMasterPixel(pl.mapId, pl.x, pl.z);
  if (!p) continue;
  const x = Math.round(p.px);
  const y = Math.round(p.py);
  const key = `${categoryId}@${x},${y}`;
  if (collectibleSeen.has(key)) continue;
  collectibleSeen.add(key);
  push(
    `${categoryId}-${x}-${y}`,
    categoryId,
    goodsById.get(pl.itemId)?.name ?? 'Item',
    p,
    { action: 'Mark as collected', doneStatus: 'Collected' },
    undefined,
    CATEGORY_ITEM_LINK[categoryId],
  );
}

markers.sort((a, b) => a.id.localeCompare(b.id));

// --- category + group metadata ---------------------------------------
// Categories with no `group` render as standalone toggles in the menu.
// `defaultHidden` categories start switched off until the user opts in.
const PLACEHOLDER = 'assets/markers/placeholder.svg';
const COLLECTED = { action: 'Mark as collected', doneStatus: 'Collected' };

const GROUPS = [
  { id: 'seeds-tears', name: 'Golden Seeds & Sacred Tears', icon: 'assets/markers/group-seeds-tears.png' },
  { id: 'upgrades', name: 'Upgrade Materials', icon: 'assets/markers/group-upgrades.png' },
  { id: 'kit', name: 'Consumables & Kit', icon: 'assets/markers/group-kit.png' },
];

// `npm run fetch:images` drops an authentic item icon at markers/<id>.png;
// until then (and for bell-bearings, which the Fan API lacks) fall back to the
// plain placeholder.
const collectibleIcon = (id) =>
  existsSync(join(MARKER_ICONS, `${id}.png`))
    ? `assets/markers/${id}.png`
    : PLACEHOLDER;

const collectible = (id, name, group) => ({
  id,
  name,
  icon: collectibleIcon(id),
  group,
  defaultHidden: true,
  completable: true,
  completion: COLLECTED,
});

const CATEGORIES = [
  {
    id: 'sites-of-grace',
    name: 'Sites of Grace',
    icon: 'assets/markers/site-of-grace.png',
    completable: true,
    completion: { action: 'Mark grace as discovered', doneStatus: 'Lost grace discovered' },
  },
  {
    id: 'bosses',
    name: 'Bosses',
    icon: 'assets/markers/boss.png',
    completable: true,
    completion: { action: 'Mark boss as felled', doneStatus: 'Enemy Felled' },
  },
  {
    id: 'dungeons',
    name: 'Dungeons',
    icon: 'assets/markers/dungeon.png',
    completable: true,
    completion: { action: 'Mark as cleared', doneStatus: 'Cleared' },
  },
  {
    id: 'merchants',
    name: 'Merchants',
    icon: 'assets/markers/merchant.png',
    completable: true,
    completion: { action: 'Mark as found', doneStatus: 'Merchant found' },
    // Optional second step, tracked separately and NOT counted as completion.
    bonusStep: {
      id: 'bell',
      action: 'Claim Bell Bearing',
      doneStatus: 'Bell Bearing claimed',
      note: 'Requires defeating the merchant.',
    },
  },
  collectible('golden-seeds', 'Golden Seeds', 'seeds-tears'),
  collectible('sacred-tears', 'Sacred Tears', 'seeds-tears'),
  collectible('larval-tears', 'Larval Tears', 'upgrades'),
  collectible('memory-stones', 'Memory Stones', 'upgrades'),
  collectible('talisman-pouches', 'Talisman Pouches', 'upgrades'),
  collectible('crystal-tears', 'Crystal Tears', 'upgrades'),
  collectible('whetblades', 'Whetblades', 'kit'),
  collectible('bell-bearings', 'Bell Bearings', 'kit'),
  collectible('cookbooks', 'Cookbooks', 'kit'),
  collectible('gloveworts', 'Gloveworts', 'kit'),
];

// --- tile existence index --------------------------------------------------
/** `{ [layer]: { [z]: [x0, y0, x1, y1, ...] } }` — only tiles that exist on disk. */
const tileIndex = {};
for (const layer of ['overworld', 'underground']) {
  const baseDir = join(TILES, layer, 'base');
  if (!existsSync(baseDir)) continue;
  const perZoom = {};
  for (const z of readdirSync(baseDir)) {
    const pairs = [];
    for (const y of readdirSync(join(baseDir, z))) {
      for (const file of readdirSync(join(baseDir, z, y))) {
        pairs.push(Number(file.replace(/\.webp$/, '')), Number(y)); // x, y
      }
    }
    perZoom[z] = pairs;
  }
  tileIndex[layer] = perZoom;
}

const tileIndexJson = JSON.stringify(tileIndex);

const catalogBody = {
  attribution:
    'Marker positions and map tiles derived from EthanShoeDev/elden-ring-compass. ' +
    'Game data and imagery © FromSoftware / Bandai Namco.',
  groups: GROUPS,
  categories: CATEGORIES,
  markers,
};

const catalog = {
  // Data version, not the app's SemVer: a content hash over the markers, the
  // category metadata and the tile index. It changes when — and only when — the
  // generated data changes, so re-running the script on an unchanged checkout is
  // a no-op (see writeIfChanged). The offline tile warm-up (MapTileCacheService)
  // re-runs whenever this value changes.
  version:
    'd' +
    createHash('sha256')
      .update(JSON.stringify(catalogBody) + tileIndexJson)
      .digest('hex')
      .slice(0, 11),
  ...catalogBody,
};

writeIfChanged(
  join(DATA_OUT, 'marker-catalog.json'),
  JSON.stringify(catalog, null, 0) + '\n',
);
writeIfChanged(join(DATA_OUT, 'map-tiles-index.json'), tileIndexJson);

const counts = markers.reduce((acc, m) => {
  acc[m.categoryId] = (acc[m.categoryId] ?? 0) + 1;
  return acc;
}, {});
console.log('marker-catalog.json:', markers.length, 'markers', counts);
console.log('map-tiles-index.json:', Object.keys(tileIndex).join(', '));
console.log('native zoom', NATIVE_ZOOM, '· master', MASTER_SIZE);
